import{createRequire}from'node:module';import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const root=new URL('.',import.meta.url),source=await readFile(new URL('display_boundary_cases.json',root)),cases=JSON.parse(source),rows=[];
const browser=await chromium.launch({headless:true,...(process.env.TURBO_CHROME_HEADLESS?{executablePath:process.env.TURBO_CHROME_HEADLESS}:{})});
try{for(const input of cases){const page=await browser.newPage();await page.setContent('<!doctype html><body></body>');await page.evaluate(code=>(0,eval)(code),input.setup);const samples=[];for(const time of input.times){samples.push(await page.evaluate(time=>{motion.currentTime=time;const timing=motion.effect.getComputedTiming();return{time,display:getComputedStyle(target).display,progress:timing.progress};},time));}const row={id:input.id,samples};if(input.restore)row.restore=await page.evaluate(()=>{target.style.display='block';const first=getComputedStyle(target).display,second=getComputedStyle(target).display;return{first,second,transitions:target.getAnimations().filter(a=>a instanceof CSSTransition).length};});rows.push(row);await page.close();}const probe=await readFile(new URL(import.meta.url)),sha=x=>createHash('sha256').update(x).digest('hex');await writeFile(new URL('display_boundary_chrome159.json',root),JSON.stringify({browser:browser.version(),casesSHA256:sha(source),probeSHA256:sha(probe),rows},null,2)+'\n');}finally{await browser.close();}
